import {cossenneServices,startConservatoryBoard,flipConservatoryCard,coverConservatoryCards,APOTHECARY_RECIPES,craftApothecary,RELIEF_POSTS,acceptRelief,prepareReliefPost,claimRelief,reliefJournal} from './cossenne-services.js?v=0.90.52';
export function handleCossenneService(id,a){const {state,room,openModal,document,$,shop,rewardTransaction,refresh,toast,showDialogue,line}=a;
 const commit=fn=>{let changed=false;const saved=rewardTransaction(()=>changed=fn());if(saved&&changed)refresh();return saved&&changed;};
 const repaint=fn=>{const top=$('.modal')?.scrollTop||0;fn();const pane=$('.modal');if(pane)pane.scrollTop=top;};
 const stock='<p><button id="cs-activity-shop">Browse specialist supplies</button></p>',bindStock=()=>{$('#cs-activity-shop')?.addEventListener('click',()=>shop(room));};
 const memory=()=>{const q=cossenneServices(state),g=q.game;openModal('Conservatory · Pollinator pairs',`<p><b>Pay:</b> 400 doubloons per completed board, plus 200 for finishing in nine turns or fewer. Your first completion also earns four Resin Loaves and a Training Tonic.</p><p>Match six habitat pairs. Turn over two tiles; study a mismatch, then cover it. No timer. Your board and progress are saved.</p>${g?`<p>Turns: <b>${g.turns}</b> · Pairs: <b>${g.matched.length/2}/6</b> · Boards completed: ${q.wins}${q.best?' · Best: '+q.best+' turns':''}</p><div class="conservatory-board" aria-label="Habitat matching board">${g.cards.map((type,i)=>{const matched=g.matched.includes(i),shown=matched||g.flipped.includes(i);return `<button data-conservatory-tile="${i}" class="${matched?'matched':shown?'revealed':''}" ${g.complete||matched||g.flipped.includes(i)||g.flipped.length===2?'disabled':''} aria-label="${shown?type:'Face-down tile '+(i+1)}"><small>${i+1}</small><b>${shown?type:'?'}</b></button>`;}).join('')}</div>${g.complete?`<p role="status"><b>Board complete · received ${g.prize} doubloons.</b> ${q.wins===1?'Your first-completion supplies are now in your bag.':''}</p><button id="cs-board-start">Play another paid board</button>`:g.flipped.length===2?'<p role="status">Different habitats. Remember these positions.</p><button id="cs-board-cover">Cover the two tiles</button>':''}`:'<button id="cs-board-start" class="primary">Start a board · free entry</button>'}<details><summary>Why the nursery runs this game</summary><p>The timber levies took the orchard’s training boards for firewood. The graftkeepers have rebuilt one to teach the next nursery crew. Match six pairs of habitat signs.</p></details>${stock}`);for(const el of document.querySelectorAll('[data-conservatory-tile]'))el.onclick=()=>{if(commit(()=>flipConservatoryCard(state,Number(el.dataset.conservatoryTile))))repaint(memory);};$('#cs-board-start')?.addEventListener('click',()=>{if(commit(()=>startConservatoryBoard(state)))repaint(memory);});$('#cs-board-cover')?.addEventListener('click',()=>{if(commit(()=>coverConservatoryCards(state)))repaint(memory);});bindStock();};
 const apothecary=()=>{openModal('Apothecary · Medicine bench',`<p>The burn ward needs concentrated medicine rather than more small dressings. Use the stillroom to turn spare Poultices into stronger treatments for your campaign.</p><p>Every recipe makes one item. Ingredients and payment are consumed together; check the cost before crafting. These medicines treat living partners.</p><p><b>Available:</b> ${state.money.toLocaleString('en-GB')} doubloons · ${state.poultices||0} Poultices.</p>${APOTHECARY_RECIPES.map(r=>`<div class="shop-row"><div><b>${r.name}</b><p>${r.text}<br>Recipe: ${r.poultices} Poultices + ${r.price} doubloons. Owned: ${state[r.key]||0}.</p></div><button data-cs-recipe="${r.id}" ${state.money>=r.price&&(state.poultices||0)>=r.poultices?'':'disabled'}>Craft one</button></div>`).join('')}${stock}`);for(const el of document.querySelectorAll('[data-cs-recipe]'))el.onclick=()=>{const r=APOTHECARY_RECIPES.find(r=>r.id===el.dataset.csRecipe);if(commit(()=>craftApothecary(state,r.id))){repaint(apothecary);toast('Crafted one '+r.name+'.');}};bindStock();};
 const firewatch=()=>{const q=cossenneServices(state).relief;openModal('Firewatch Cistern · A road for relief',`<p><b>What happened:</b> the army took the ditch crews and the wildfire scattered the civilian supply teams. Common Cause carts now carry seed, water and dressings to families from both sides, but the three roadside posts are unprepared.</p><p><b>Objective:</b> help Waterkeeper Ali reopen the relief chain, then report back here. This is a separate job from opening the two town reservoir valves.</p><p><b>How:</b> accept the dispatch below. Travel west along Orchard Way and press A beside each labelled relief crate: The Green Return’s seed post, Ashfall Slope’s water post and the Firebreak’s dressings post. Check the supplies and clear the damaged shelter at each. Visit in any order, then return to this board.</p><p><b>Reward:</b> 2,500 doubloons, two Armed Escorts and two Cleansing Balms. Completion permanently reduces Cossenne’s specialist food and medicine prices by 10%.</p><ul>${RELIEF_POSTS.map(p=>`<li>${q.posts.includes(p.key)?'Ready':'To prepare'} · ${p.name}</li>`).join('')}</ul><p role="status">${reliefJournal(state)}</p>${q.claimed?'<p><b>Payment received and discount active.</b></p>':!q.accepted?'<button id="cs-relief-accept" class="primary">Accept the relief dispatch</button>':`<button id="cs-relief-claim" class="primary" ${q.posts.length===3?'':'disabled'}>Report all three posts · collect reward</button>`}${stock}`);$('#cs-relief-accept')?.addEventListener('click',()=>{if(commit(()=>acceptRelief(state)))repaint(firewatch);});$('#cs-relief-claim')?.addEventListener('click',()=>{if(commit(()=>claimRelief(state))){repaint(firewatch);toast('Relief chain restored · reward received and specialist discount unlocked.');}});bindStock();};
 if(id==='cs-conservatory-work'){memory();return true;}if(id==='cs-apothecary-work'){apothecary();return true;}if(id==='cs-firewatch-work'){firewatch();return true;}if(id==='cs-specialist-stock'){shop(room);return true;}
 const post=RELIEF_POSTS.find(p=>p.id===id&&p.room===room);if(post){const q=cossenneServices(state).relief;if(!q.accepted){showDialogue([line('Relief post','The shelter is empty and the manifest has no carrier’s mark. Visit the Firewatch Cistern in southeast Cossenne and accept Ali’s relief dispatch before preparing this post.')]);return true;}let done=false;if(!q.claimed&&!q.posts.includes(post.key))done=commit(()=>prepareReliefPost(state,post.key,room));showDialogue([line(post.name,done?({firebreak:'You clear ash from the shelter and seal the clean dressings above the damp ground. The next wagon has a place to stop.',slope:'You uncover the water jars and replace the torn cloth over the settling tank. Travellers can refill without taking water from the burn ward.',renewal:'You secure the seed sacks beneath the repaired awning and mark the loads reserved for households, rather than either army.'}[post.key])+' '+reliefJournal(state):'This post is prepared. '+reliefJournal(state))]);return true;}
 return false;
}
